module TopModule (
    input clk,
    input areset,
    input in,
    output out
);

    // State encoding: A = 0, B = 1
    // out is 1 when in state B, 0 when in state A
    reg state;
    reg next_state;

    // Moore output: out = state (since B=1 -> out=1, A=0 -> out=0)
    assign out = state;

    // Next state logic
    always @(*) begin
        case (state)
            1'b0: begin // State A
                if (in)
                    next_state = 1'b0; // A --1--> A
                else
                    next_state = 1'b1; // A --0--> B
            end
            1'b1: begin // State B
                if (in)
                    next_state = 1'b1; // B --1--> B
                else
                    next_state = 1'b0; // B --0--> A
            end
            default:
                next_state = 1'b0;
        endcase
    end

    // State flip-flop with asynchronous reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 1'b1; // Reset to state B
        else
            state <= next_state;
    end

endmodule
